#include <unity.h>
#define private public
#include "synth.h"
#undef private
using namespace mt;
static SynthModel model;static Synth* synth;
void setUp(){model=SynthModel();instrSetType(model.instruments[0],InstrType::Synth);model.instruments[0].synOsc[0]=uint8_t(SynOsc::Saw);model.instruments[0].synOsc[1]=uint8_t(SynOsc::Saw);model.tracks[0].instr=0;model.tracks[0].out=TrackOut::Int;synth=new Synth(model);synth->setVoiceBudget(kVoiceBudgetTeensy);}
void tearDown(){delete synth;}
static Voice& note(){synth->noteOn(0,60,127);for(auto& v:synth->voices_)if(v.on)return v;TEST_FAIL_MESSAGE("missing voice");return synth->voices_[0];}
void test_follower_cost_reserved_on_note_on(){auto& t=model.tracks[0];t.folSrc=1;t.folAmt=1;t.folDest=uint8_t(LfoDest::Fold);TEST_ASSERT_EQUAL(kCostSynBl+kCostFold,note().cost);}
void test_lfo_destination_lock_cost_reserved_on_note_on(){synth->rt_[0].lfoLockMask=1u<<kLfoLkDest;synth->rt_[0].lfoLock[0].dest=uint8_t(LfoDest::Ring);TEST_ASSERT_EQUAL(kCostSynBl+kCostRing,note().cost);}
void test_sat_lock_cost_reserved_on_note_on(){instrSetType(model.instruments[0],InstrType::Fm);synth->rt_[0].lockMask=1u<<kLockSat;synth->rt_[0].lock[kLockSat]=127;TEST_ASSERT_EQUAL(kCostFm+kCostFmSat,note().cost);}
void test_live_instrument_cost_updates(){auto& v=note();TEST_ASSERT_EQUAL(kCostSynBl,v.cost);model.instruments[0].synFold=127;synth->cacheInstrument(0);synth->control(v,32);TEST_ASSERT_EQUAL(kCostSynBl+kCostFold,v.cost);model.instruments[0].synFold=0;synth->cacheInstrument(0);synth->control(v,32);TEST_ASSERT_EQUAL(kCostSynBl,v.cost);}
void test_fading_stolen_voice_does_not_reenter_budget(){auto& v=note();v.stolen=true;model.instruments[0].synFold=127;synth->cacheInstrument(0);synth->control(v,32);TEST_ASSERT_TRUE(v.stolen);TEST_ASSERT_TRUE(v.syn);TEST_ASSERT_EQUAL(kCostSynBl+kCostFold,v.cost);}
void test_budget_off_skips_live_scan_then_enable_refreshes(){auto& v=note();synth->setVoiceBudget(kVoiceBudgetOff);model.instruments[0].synFold=127;synth->cacheInstrument(0);synth->control(v,32);TEST_ASSERT_EQUAL(kCostSynBl,v.cost);synth->setVoiceBudget(kVoiceBudgetTeensy);synth->control(v,32);TEST_ASSERT_EQUAL(kCostSynBl+kCostFold,v.cost);}
void test_live_follower_and_lfo_lock_cost_updates(){auto& v=note();model.tracks[0].folSrc=1;model.tracks[0].folAmt=1;model.tracks[0].folDest=uint8_t(LfoDest::Fold);v.lfoLockMask=1u<<kLfoLkDest;v.lfoLock[0].dest=uint8_t(LfoDest::Ring);synth->control(v,32);TEST_ASSERT_EQUAL(kCostSynBl+kCostFold+kCostRing,v.cost);}
static Voice& restartEngine(InstrType type,int machine){delete synth;model=SynthModel();instrSetType(model.instruments[0],type);model.instruments[0].machine=machine;model.tracks[0].out=TrackOut::Int;model.tracks[0].instr=0;synth=new Synth(model);synth->setVoiceBudget(kVoiceBudgetTeensy);return note();}
void test_live_voice_cost_uses_latched_engine(){auto& v=note();model.instruments[0].type=InstrType::Fm;synth->cacheInstrument(0);synth->control(v,32);TEST_ASSERT_EQUAL(kCostSynBl,v.cost);}
void test_live_voice_cost_uses_latched_drum_machine(){auto& v=restartEngine(InstrType::Drum,int(DrumMachine::Hhr));model.instruments[0].machine=uint8_t(DrumMachine::Bda);synth->cacheInstrument(0);synth->control(v,32);TEST_ASSERT_EQUAL(kCostDrum2[7],v.cost);}
void test_live_byte_cost_stays_byte_after_ui_change(){auto& v=restartEngine(InstrType::Lofi,int(LofiMachine::Byte));const auto oldCost=v.cost;model.instruments[0].machine=uint8_t(LofiMachine::Apc);synth->cacheInstrument(0);synth->control(v,32);TEST_ASSERT_EQUAL(oldCost,v.cost);model.instruments[0].type=InstrType::Chip;synth->cacheInstrument(0);synth->control(v,32);TEST_ASSERT_EQUAL(oldCost,v.cost);}
void test_ay_cost_uses_note_frequency(){auto& m=model.instruments[0];m.type=InstrType::Chip;m.wave=uint8_t(Wave::AyToneNoise);TEST_ASSERT_EQUAL(199,note().cost);}
void test_ay_live_cost_uses_current_lfo_pitch(){auto& m=model.instruments[0];m.type=InstrType::Chip;m.wave=uint8_t(Wave::AyToneNoise);m.transpose=24;m.lfoDest=uint8_t(LfoDest::Pitch);m.lfoWave=uint8_t(LfoWave::Square);m.lfoDepth=63;synth->noteOn(0,127,127);Voice* v=nullptr;for(auto& x:synth->voices_)if(x.on)v=&x;TEST_ASSERT_NOT_NULL(v);TEST_ASSERT_EQUAL(349,v->cost);m.lfoDepth=0;synth->cacheInstrument(0);synth->control(*v,32);TEST_ASSERT_EQUAL(249,v->cost);}
int main(){UNITY_BEGIN();RUN_TEST(test_follower_cost_reserved_on_note_on);RUN_TEST(test_lfo_destination_lock_cost_reserved_on_note_on);RUN_TEST(test_sat_lock_cost_reserved_on_note_on);RUN_TEST(test_live_instrument_cost_updates);RUN_TEST(test_fading_stolen_voice_does_not_reenter_budget);RUN_TEST(test_budget_off_skips_live_scan_then_enable_refreshes);RUN_TEST(test_live_follower_and_lfo_lock_cost_updates);RUN_TEST(test_live_voice_cost_uses_latched_engine);RUN_TEST(test_live_voice_cost_uses_latched_drum_machine);RUN_TEST(test_live_byte_cost_stays_byte_after_ui_change);RUN_TEST(test_ay_cost_uses_note_frequency);RUN_TEST(test_ay_live_cost_uses_current_lfo_pitch);return UNITY_END();}
